class DcEscalationModel extends CI_Model {

  public function __construct() {
    parent::__construct();
    $this->load->model('AutoEscalationmodel');
    $this->load->model('Escalationmodel');
    $this->load->model('EscTableFieldsModel');
  }


  // get detail from escalation details by case no
  public function getEscalationDetailsByCaseNo($case_no, $db)
  {
    return $db->query("SELECT * FROM escalation_details WHERE case_no=?", array($case_no));
  }

  // get escalated list
  public function getEscalationFromUserToDc($user_desig_code, $user_code)
  {  
    $json         = array();
    $user         = json_decode(USER_ALLOT_CODE);
    $dc_esc_code  = $user[1]->CODE; 
    $co_esc_code  = $user[5]->CODE;
    $adc_esc_code = $user[2]->CODE;
    $lm_esc_code  = $user[8]->CODE;
    $bo_esc_code  = $user[4]->CODE;

    // get escalated cases from LM
    // $escalatedfromLm = $this->getEscalatedListFromUser($user_code, $dc_esc_code, $lm_esc_code);

    // get escalated cases from CO
    $escalatedfromCo = $this->getEscalatedListFromUser($user_code, $dc_esc_code, $co_esc_code);

    // get escalated cases from ADC
    $escalatedfromAdc= $this->getEscalatedListFromUser($user_code, $dc_esc_code, $adc_esc_code);

    // get escalated cases from BO
    $escalatedfromBo = $this->getEscalatedListFromUser($user_code, $dc_esc_code, $bo_esc_code);

    $json = [
      'escalatedfromLm'  => 0,
      'escalatedfromCo'  => $escalatedfromCo->num_rows(),
      'escalatedfromBo'  => $escalatedfromBo->num_rows(),
      'escalatedfromAdc' => $escalatedfromAdc->num_rows(),
    ];
    log_message('error','JSON21'.json_encode($json));
    return $json;
  }
    
  // get escalated list from CO
  public function getEscalatedListFromUser($user_code, $dc_code, $from_code) 
  {
    $esc_field_status = $this->AutoEscalationmodel->checkEscalatedStatus($from_code);

    $query = $this->db->query("SELECT * FROM escalation_details WHERE 
                assigned_to_code=? AND assigned_from_code=? AND status=? 
                AND final_completion_date IS NULL AND $esc_field_status=? AND 
                (dc_escalate_status=? OR dc_escalate_status IS NULL)", 
                array($dc_code, $from_code, 'P', 'Y', 'N'));

    // log_message('error',"#ERR62: getEscalatedListFromCo($user_code, $dc_code, $from_code): ".$this->db->last_query());
    return $query;    
  }

  // explode service type by case no
  public function explodeCaseNo($case_no)
  {
    $get_case_no = explode('/', $case_no);
    $c_no = $get_case_no['4'];
    return $c_no;
  }

  // get 
  public function getEscalatedCasesToDcByOtherUsers($user_code,$from_user_code)
  {
    $assigned_from_code = $this->EscTableFieldsModel->getUserCode($from_user_code);
    $escalate_status    = $this->EscTableFieldsModel->getEscalatedStatusByUserCode($from_user_code);
    $query = $this->db->query("SELECT * FROM escalation_details WHERE $escalate_status = ? AND
                assigned_from_code = ? AND assigned_to=? AND assigned_to_code=? AND status=?
                AND final_completion_date IS NULL AND 
                (dc_escalate_status=? OR dc_escalate_status IS NULL)", 
                array('Y', $assigned_from_code, $user_code, '2', 'P', 'N'));
    return $query;
  }

  // get total remaining days of users
  public function getEscRemainingDaysOfUsers($case_no, $db)
  {
    $res = $db->query("SELECT * FROM escalation_details WHERE case_no=? AND 
                final_completion_date IS NULL", array($case_no))->row();
    // echo $db->last_query();

    $remaining_days_for_ast   = $res->da_target_days - $res->da_completed_days;             // AST    
    $remaining_days_for_lm    = $res->lm_target_days - $res->lm_completed_days;             // LM
    $remaining_days_for_sk    = $res->sk_target_days - $res->sk_completed_days;             // SK
    $remaining_days_for_co    = $res->co_target_days - $res->co_completed_days;             // CO
    $remaining_days_for_bo    = $res->bo_target_days - $res->bo_completed_days;             // BO
    $remaining_days_for_adc   = $res->adc_target_days - $res->adc_completed_days;           // ADC
    $remaining_days_for_dc    = $res->dc_target_days - $res->dc_completed_days;             // DC
    $remaining_days_for_dept  = $res->dept_target_days - $res->dept_completed_days;         // DEPT
    $remaining_days_for_sro   = $res->sro_target_days - $res->sro_completed_days;           // SRO
    $remaining_days_for_mouza = $res->mouzadar_target_days - $res->mouzadar_completed_days; // MOUZADAR

    $user_total_remain_days   = $remaining_days_for_ast + $remaining_days_for_lm + $remaining_days_for_sk
                              + $remaining_days_for_co + $remaining_days_for_bo 
                              + $remaining_days_for_adc + $remaining_days_for_dc 
                              + $remaining_days_for_dept + $remaining_days_for_sro 
                              + $remaining_days_for_mouza;

    // $service_total_remain_days = $res->total_days - $user_total_remain_days;

    $service_total_remain_days = $user_total_remain_days;

    // user completed days count
    $user_completed_days = $res->da_completed_days+$res->lm_completed_days
                          +$res->sk_completed_days+$res->co_completed_days
                          +$res->bo_completed_days+$res->adc_completed_days
                          +$res->dc_completed_days+$res->dept_completed_days
                          +$res->sro_completed_days+$res->mouzadar_completed_days;

    $array = [  
      'user_rem_days' => [
        'remaining_days_for_ast'   => $remaining_days_for_ast,
        'remaining_days_for_lm'    => $remaining_days_for_lm,
        'remaining_days_for_sk'    => $remaining_days_for_sk,
        'remaining_days_for_co'    => $remaining_days_for_co,
        'remaining_days_for_bo'    => $remaining_days_for_bo,
        'remaining_days_for_adc'   => $remaining_days_for_adc,
        'remaining_days_for_dc'    => $remaining_days_for_dc,
        // 'remaining_days_for_dept'  => $remaining_days_for_dept,
        // 'remaining_days_for_sro'   => $remaining_days_for_sro,
        // 'remaining_days_for_mouza' => $remaining_days_for_mouza,
      ],    
      'total_rem_days'      => $service_total_remain_days,
      'total_allocate_days' => $res->total_days,
      'total_complete_days' => $user_completed_days,
    ];
    return $array;
  }

