  // switch to methods as per requirement
  public function revertBackEscalationCasesByDc($postData, $db)
  {
    $data = $this->utilityclass->decryptJwtCase($postData['env']);
    if($data == REVERT)
    {
      return $this->updateEscalationDetailsForRevert($postData, $db);
    }
    else if($data == DEESCALATE)
    {
      return $this->updateEscalationDetailsForDeEscalation($postData, $db);
    }
    else 
    {
      return 'n';
    }
  }


  // update escalation details for normal revert
  public function updateEscalationDetailsForRevert($postData, $db)
  {
    $json               = array();
    $currDate           = date('Y-m-d H:i:s');
    $allocate_day       = $postData['allocate_day'];
    $revert_to_user     = $postData['revert_to_user'];
    $case_no            = $postData['case_no'];
    $executionDate      = $postData['executionDate'];
    $revert_remarks     = $postData['revert_remarks'];
    $dataArray          = json_decode($postData['dataArray'], true);
    // var_dump($dataArray);
    // die;
    $assigned_from      = $this->session->userdata('user_code');
    $assigned_from_code = 2;
    $revert_previous_user_escalate_status = $this->EscTableFieldsModel->getEscalatedStatusByUserCode($revert_to_user);
    $case_no_en         = $this->utilityclass->encryptJwtCase($case_no);
    $revert_to_user_en  = $this->utilityclass->encryptJwtCase($revert_to_user);

    if($allocate_day == 0 || $allocate_day == null || $allocate_day == '')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR308: Revert to $revert_to_user for case no $case_no is failed. Allocate days can not be zero(0) !!!!!",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    else if($revert_remarks == null || $revert_remarks == '')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR319: Revert to $revert_to_user for case no $case_no is failed. Remark field is mandatory !!!!!",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    $allocate_days_field= $this->EscTableFieldsModel->getAllocatedDaysFieldName($revert_to_user);
    $target_days_field  = $this->EscTableFieldsModel->getTargetDaysFieldName($revert_to_user);

    // insert into escalation dates details

    $res = $this->getEscalationDetailsByCaseNo($case_no, $db)->row();

    $action_type = json_decode(ASSIGNMENT_TYPE);
    $action_type = $action_type[1]->CODE;


    if($revert_to_user == 'AST')
    {
      // $assigned_to                 = 'assignment_type_other';
      $assigned_to                 = 'assigned_other_code';
      $assigned_to_code            = 'assigned_other';
      $assigned_date               = 'assigned_other_date';
      $assigned_es_date            = 'assigned_other_es_date';
      $to_be_completed_within_days = 'to_be_other_completed_within_days';
    }
    else
    {
      $assigned_to                 = 'assigned_to';
      $assigned_to_code            = 'assigned_to_code';
      $assigned_date               = 'assigned_date';
      $assigned_es_date            = 'escalated_date';
      $to_be_completed_within_days = 'to_be_completed_within_days';
    }

    if(ESCALATION_ALLOW_TIME == 1)
    {
      $allocateDate = date('Y-m-d H:i:s');
      $target_completion_date = date("Y-m-d H:i:s", strtotime($allocateDate)+(60*$allocate_day));
      $date_diff = $this->Escalationmodel->dateDiff($target_completion_date, $allocateDate);
      $dc_rev_days = $this->Escalationmodel->dateDiff($executionDate, $res->assigned_date);
    }
    else
    {
      $allocateDate = date('Y-m-d');
      if($postData['allocate_days'] == 1)
      {
        $target_completion_date = date('Y-m-d', strtotime($allocateDate. ' + 1 day'));
      }
      else
      {
        $target_completion_date = date('Y-m-d', strtotime($allocateDate. ' + '.$allocate_day.' days'));
      }
      $date_diff = $this->Escalationmodel->dateDiff($target_completion_date, $allocateDate);
      $dc_rev_days = $this->Escalationmodel->dateDiff($executionDate, $res->assigned_date);
    }

    $date_code = $this->Escalationmodel->generateDateCode();
    $date_code_history = $this->getDateCode($revert_to_user, $case_no, $db);

    $petitionDetails = $this->getEscalationDetailsByCaseNo($case_no, $db)->row();
    $updateFlag = true;
    if($petitionDetails->assigned_other != null) {
      $updateFlag = false;
      $history_id = $petitionDetails->history_id_others;
    } else {
      $updateFlag = true;
      $history_id = $petitionDetails->history_id;
    }


    $where_history = array(
      'petition_no' => $petitionDetails->petition_no,
      'date_code'   => $history_id,
      'service_code'=> $petitionDetails->service_code,
    );
    $updateDatesArray = array(
        'completion_date'     => $executionDate,
        // 'escalated_status'    => $escalate_status,
        'completion_days'     => $dc_rev_days, 
    );

    $updateStatus22 = $db->update('escalation_dates_details',$updateDatesArray ,$where_history);
    log_message('error','00'.$db->last_query());
    if($db->affected_rows() != 1)
    {
      log_message('error', "#ERR414: insertion failed in escalation_dates_details for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR414: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }


    // insert into escalation dates details
    $ins = [
      'date_code'              => $date_code,
      'petition_no'            => $res->petition_no,
      'service_code'           => $res->service_code,
      'taskid'                 => 20,
      'action_type'            => $action_type,
      'pending_officer'        => $res->assigned_from,
      'assigned_user'          => $this->session->userdata('user_code'),
      'assigned_user_code'     => 2,
      'assigned_to'            => $res->assigned_from,
      'assigned_to_code'       => $res->assigned_from_code,
      'registerd_on'           => $res->registerd_on,
      'allocation_date'        => $currDate,
      'target_completion_date' => $target_completion_date,
      'date_diff'              => $date_diff,
      'escalated_status'       => 'N',
      'created_date'           => $currDate,
      'updated_date'           => $currDate,
    ];
    $insert = $db->insert('escalation_dates_details', $ins);
    if($insert != 1)
    {
      log_message('error', "#ERR407: insertion failed in escalation_dates_details for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR407: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }

    if(isset($dataArray) && !empty($dataArray)) // if days taken from user
    {
      // update escalation details table
      $updateEscDetTable = [
        'assignment_type'            => 4,
        'assigned_from'              => $this->session->userdata('user_code'),
        'assigned_from_code'         => 2,
        'history_id'                 => $date_code,
        $assigned_to_code            => $res->assigned_from_code,
        $assigned_to                 => $res->assigned_from,
        $assigned_date               => $executionDate,
        $assigned_es_date            => $target_completion_date,
        $to_be_completed_within_days => $allocate_day,
        'dc_target_days'             => $dc_rev_days,
        'dc_allocate_days'           => $dc_rev_days,
        'dc_completed_days'          => $dc_rev_days,
        'dc_date_code_list'          => $date_code_history,
        $allocate_days_field         => $res->$allocate_days_field + $allocate_day,
        $target_days_field           => $res->$target_days_field + $allocate_day,
        // $dataArray['completed_days'] => $dataArray['completed_days'] + $allocate_day,
        $dataArray['completed_days'] => $dc_rev_days,
        $revert_previous_user_escalate_status => 'N',  
        'dc_escalate_status' => 'N',       
      ];
      log_message('error','DC#MRIG=============='.json_encode($updateEscDetTable));
      $db->where('case_no', $case_no);
      $db->where('final_completion_date IS NULL');
      $db->update('escalation_details', $updateEscDetTable);

      log_message('error', "#ERR479: UPDATE_QUERY: ".json_encode($db->last_query()));

      if($db->affected_rows() != 1)
      {
        log_message('error', "#ERR442: updation failed in escalation_details for case no $case_no and query : ".$db->last_query());
        $json = [
          'response' => 1,
          'message'  => "#ERR442: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
          'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
        ];
        return $json;
      } 
    }
    else // if days taken from total remaining days
    {
      // update escalation details table
      $updateEscDetTable = [
