  // update escalation details for de-escaltion revert
  public function updateEscalationDetailsForDeEscalation($postData, $db)
  {
    $json               = array();
    $currDate           = date('Y-m-d H:i:s');
    $allocate_day       = 0;
    $revert_to_user     = $postData['revert_to_user'];
    $case_no            = $postData['case_no'];
    $executionDate      = $postData['executionDate'];
    $revert_remarks     = $postData['revert_remarks'];
    // $dataArray          = json_decode($postData['dataArray'], true);
    $assigned_from      = $this->session->userdata('user_code');
    $assigned_from_code = 2;

    if($revert_remarks == null || $revert_remarks == '')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR562: Revert to $revert_to_user for case no $case_no is failed. Remark field is mandatory !!!!!",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    $date_code = $this->Escalationmodel->generateDateCode();
    $date_code_history = $this->getDateCode($revert_to_user, $case_no, $db);


    // get service type
    $service_type = $this->explodeCaseNo($case_no);

    // get de escalation time line
    $time = $this->getServiceWiseEscMatrixDetail($service_type, $db, DEESCALATE)->row();


    // insert into escalation dates details
    $res = $db->query("SELECT * FROM escalation_details WHERE case_no=?", array($case_no))->row();

    $action_type = json_decode(ASSIGNMENT_TYPE);
    $action_type = $action_type[2]->CODE;

    $assigned_days = $this->EscTableFieldsModel->getUserWiseTimeAllocate($service_type, DEESCALATE, $revert_to_user, $db);

    if(ESCALATION_ALLOW_TIME == 1)
    {
      $allocateDate = date('Y-m-d H:i:s');
      $target_completion_date = date( "Y-m-d H:i:s", strtotime($allocateDate)+(60*$assigned_days));
      $date_diff = $this->Escalationmodel->dateDiff($target_completion_date, $allocateDate);
      $dc_rev_days = $this->Escalationmodel->dateDiff($executionDate, $res->assigned_date);
    }
    else
    {
      $allocateDate = date('Y-m-d');
      if($assigned_days == 1)
      {
        $target_completion_date = date('Y-m-d', strtotime($allocateDate. ' + 1 day'));
      }
      else
      {
        $target_completion_date = date('Y-m-d', strtotime($allocateDate. ' + '.$assigned_days.' days'));
      }
      $date_diff = $this->Escalationmodel->dateDiff($target_completion_date, $allocateDate);
      $dc_rev_days = $this->Escalationmodel->dateDiff($executionDate, $res->assigned_date);
    }


    // get max proceeding no
    $proceeding_id = $this->db->query("SELECT max(proceeding_id)+1 AS c FROM escalation_procceding 
                      WHERE case_no=?", array($case_no))->row()->c;
    if($proceeding_id == null || $proceeding_id == '')
    {
        $proceeding_id = 1;
    }  

    // insert into escalation proceeding
    $insProceeding = [
      'task_id'        => 19,
      'action_type'    => $action_type,
      'petition_no'    => $res->petition_no,
      'case_no'        => $case_no,
      'proceeding_id'  => $proceeding_id,
      'revert_remarks' => $revert_remarks,
      'status'         => 1,
      'user_code'      => $this->session->userdata('user_code'),
      'date_entry'     => date('Y-m-d H:i:s'),
      'ip'             => $_SERVER['REMOTE_ADDR'],
    ];
    $insertPro = $db->insert('escalation_procceding', $insProceeding);
    if($insertPro != 1)
    {
      log_message('error', "#ERR627: insertion failed in escalation_procceding for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR627: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }

    // insert into escalation dates details
    $ins = [
      'date_code'              => $date_code,
      'petition_no'            => $res->petition_no,
      'service_code'           => $res->service_code,
      'taskid'                 => 19,
      'action_type'            => $action_type,
      'pending_officer'        => $res->assigned_from,
      'assigned_user'          => $this->session->userdata('user_code'),
      'assigned_user_code'     => 2,
      'assigned_to'            => $res->assigned_from,
      'assigned_to_code'       => $res->assigned_from_code,
      'registerd_on'           => $res->registerd_on,
      'allocation_date'        => $currDate,
      'target_completion_date' => $target_completion_date,
      'date_diff'              => $date_diff,
      'escalated_status'       => 'N',
      'created_date'           => $currDate,
      'updated_date'           => $currDate,
    ];
    $insert = $db->insert('escalation_dates_details', $ins);
    if($insert != 1)
    {
      log_message('error', "#ERR659: insertion failed in escalation_dates_details for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR659: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }

    if($revert_to_user == 'AST')
    {
      // $assigned_to                 = 'assignment_type_other';
      $assigned_to                 = 'assigned_other_code';
      $assigned_to_code            = 'assigned_other';
      $assigned_date               = 'assigned_other_date';
      $assigned_es_date            = 'assigned_other_es_date';
      $to_be_completed_within_days = 'to_be_other_completed_within_days';
    }
    else
    {
      $assigned_to                 = 'assigned_to';
      $assigned_to_code            = 'assigned_to_code';
      $assigned_date               = 'assigned_date';
      $assigned_es_date            = 'escalated_date';
      $to_be_completed_within_days = 'to_be_completed_within_days';
    }


    // update escalation details table
    $updateEscDetTable = [
      'assignment_type'            => 3,
      'assigned_from'              => $this->session->userdata('user_code'),
      'assigned_from_code'         => 2,
      'history_id'                 => $date_code,
      $assigned_to_code            => $res->assigned_from_code,
      $assigned_to                 => $res->assigned_from,
      $assigned_date               => $executionDate,
      $assigned_es_date            => $target_completion_date,
      $to_be_completed_within_days => $assigned_days,
      'dc_target_days'             => $dc_rev_days,
      'dc_completed_days'          => $dc_rev_days,
      'dc_date_code_list'          => $date_code_history,
      'total_days'                 => $res->total_days + $time->total_timeline,
      'da_target_days'          => $res->da_target_days + $time->da_allocated_days,
      'da_escalate_status'         => 'N',
      'lm_target_days'          => $res->lm_target_days + $time->lm_allocated_days,
      'lm_escalate_status'         => 'N',
      'sk_target_days'          => $res->sk_target_days + $time->sk_allocated_days,
      'sk_escalate_status'         => 'N',
      'co_target_days'          => $res->co_target_days + $time->co_allocated_days,
      'co_escalate_status'         => 'N',
      'bo_target_days'          => $res->bo_target_days + $time->bo_allocated_days,
      'bo_escalate_status'         => 'N',
      'adc_target_days'         => $res->adc_target_days + $time->adc_allocated_days,
      'adc_escalate_status'        => 'N',
      'dc_target_days'          => $res->dc_target_days + $time->dc_allocated_days,
      'dc_escalate_status'         => 'N',
      'dept_target_days'        => $res->dept_target_days + $time->dept_allocated_days,
      'dept_escalate_status'       => 'N',
      'sro_target_days'         => $res->sro_target_days + $time->sro_allocated_days,
      'sro_escalate_status'        => 'N',
      'mouzadar_target_days'    => $res->mouzadar_target_days + $time->mouzadar_allocated_days,
      'mouzadar_escalate_status'   => 'N',
      'updated_date'               => date('Y-m-d H:i:s'),
      'deescalation_start_date'    => date('Y-m-d H:i:s'),
      'deescalation_status'        => 'Y',
    ];
    $db->where('case_no', $case_no);
    $db->where('final_completion_date IS NULL');
    $db->update('escalation_details', $updateEscDetTable);

    if($db->affected_rows() != 1)
    {
      log_message('error', "#ERR734: updation failed in escalation_details for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR734: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }   


    $updateTable = $this->AutoEscalationmodel->updateIsEscToZeroServiceWiseTable($case_no);
    if($updateTable == 'n')
    {
      log_message('error', "#ERR533: updation failed in service wise table for case no $case_no and query : ".$db->last_query());
      $json = [
        'response' => 1,
        'message'  => "#ERR533: Revert to $revert_to_user for case no $case_no is failed. Kindly contact system administrator",
        'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
      ];
      return $json;
    }


    $json = [
      'response' => 3,
      'message'  => "#ERR520: Successfully reverted the case to $revert_to_user for case no $case_no",
      'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
    ];
    return $json;
  }



  // get date code history
  public function getDateCode($user_desig_code, $case_no, $db)
  {
    $prevDateCodes = $this->getUserWiseDateCodesHistory($user_desig_code, $case_no, $db);
    $date_code = $this->Escalationmodel->generateDateCode();
    if($prevDateCodes == null)
    {
      $date_code = $date_code;
    }
    else
    {
      $date_code = $prevDateCodes.','.$date_code;
    }
    return $date_code;
  }


  // get date code list field from escalation matrix
  public function getUserWiseDateCodesHistory($user_desig_code, $case_no, $db)
  {
    $query = $db->query("SELECT * FROM escalation_details WHERE case_no=? AND 
                final_completion_date IS NULL", array($case_no))->row();

    $date_code_list = null;
    if($user_desig_code == 'AST')
    {
      $date_code_list = $query->da_date_code_list;
    }
    else if($user_desig_code == 'LM')
    {
      $date_code_list = $query->lm_date_code_list;
    }
    else if($user_desig_code == 'SK')
    {
      $date_code_list = $query->sk_date_code_list;
    }
    else if($user_desig_code == 'CO')
    {
      $date_code_list = $query->co_date_code_list;
    }
    else if($user_desig_code == 'BO')
    {
      $date_code_list = $query->bo_date_code_list;
    }
    else if($user_desig_code == 'ADC')
    {
      $date_code_list = $query->adc_date_code_list;
    }
    else if($user_desig_code == 'DC')
    {
      $date_code_list = $query->dc_date_code_list;
    }
    else if($user_desig_code == 'DEPT')
    {
      $date_code_list = $query->dept_date_code_list;
    }
    else if($user_desig_code == 'SRO')
    {
      $date_code_list = $query->sro_date_code_list;
    }
    else if($user_desig_code == 'MOUZADAR')
    {
      $date_code_list = $query->mouzadar_date_code_list;
    }
    return $date_code_list;
  }

