  // get from escalation matrix master
  public function getFromEscalationMatrix($service_code, $service_type, $esc_type, $db)
  {
    if($service_type == 'MiNC')
    {
      $service_type = 'NCOR';
    }
    if($service_type == 'MiND')
    {
      $service_type = 'NCAN';
    }

    $res = $db->query("SELECT * FROM escalation_matrix WHERE service_code=? AND escalation_type=? 
            AND category=?", array($service_code, $esc_type, $service_type))->row();
    return $res;
  }

  // update service wise table to out of escalation concept
  protected function updateServiceTable($table, $case_no, $db)
  {
