  }

  protected function updateServiceTableMinC($table, $case_no, $db)
  {
    $update = $db->query("UPDATE $table SET out_of_esc=? WHERE misc_case_no=?", array(1, $case_no));
  }


  // check if LM/AST/SK has given any report
  public function checkForReportGiven($case_no, $db)
  {
    $json = array();

    // details from escalation_details table
    $row = $this->getAllFromEscalationDetails($case_no, $db);

    $lmRemainingDays = $row->lm_target_days - $row->lm_completed_days;
    if($lmRemainingDays == $row->lm_target_days)
    {
      $new_lm_target_days = 0;
      $new_lm_completed_days = 0;
    }
    else
    {
      $new_lm_target_days = $row->lm_completed_days;
      $new_lm_completed_days = $row->lm_completed_days;
    }

    $skRemainingDays = $row->sk_target_days - $row->sk_completed_days;
    if($skRemainingDays == $row->sk_target_days)
    {
      $new_sk_target_days = 0;
      $new_sk_completed_days = 0;
    }
    else
    {
      $new_sk_target_days = $row->sk_completed_days;
      $new_sk_completed_days = $row->sk_completed_days;
    }

    $coRemainingDays = $row->co_target_days - $row->co_completed_days;
    if($coRemainingDays == $row->co_target_days)
    {
      $new_co_target_days = 0;
      $new_co_completed_days = 0;
    }
    else
    {
      $new_co_target_days = $row->co_completed_days;
      $new_co_completed_days = $row->co_completed_days;
    }

    $daRemainingDays = $row->da_target_days - $row->da_completed_days;
    if($daRemainingDays == $row->da_target_days)
    {
      $new_da_target_days = 0;
      $new_da_completed_days = 0;
    }
    else
    {
      $new_da_target_days = $row->da_completed_days;
      $new_da_completed_days = $row->da_completed_days;
    }

    $adcRemainingDays = $row->adc_target_days - $row->adc_completed_days;
    if($adcRemainingDays == $row->adc_target_days)
    {
      $new_adc_target_days = 0;
      $new_adc_completed_days = 0;
    }
    else
    {
      $new_adc_target_days = $row->adc_completed_days;
      $new_adc_completed_days = $row->adc_completed_days;
    }

    $total_remaining_days_for_dc = $lmRemainingDays + $skRemainingDays + $coRemainingDays + $daRemainingDays + $adcRemainingDays;

    $json = [
      'new_lm_target_days'          => $new_lm_target_days,
      'new_lm_completed_days'       => $new_lm_completed_days,
      'new_sk_target_days'          => $new_sk_target_days,
      'new_sk_completed_days'       => $new_sk_completed_days,
      'new_co_target_days'          => $new_co_target_days,
      'new_co_completed_days'       => $new_co_completed_days,
      'new_da_target_days'          => $new_da_target_days,
      'new_da_completed_days'       => $new_da_completed_days,
      'new_adc_target_days'         => $new_adc_target_days,
      'new_adc_completed_days'      => $new_adc_completed_days,
      'total_remaining_days_for_dc' => $total_remaining_days_for_dc,
    ];

    return $json;

  }


  // assign days percentage wise
  public function allocateDaysToUserFromDc($case_no, $remaining_days, $db)
  {
    $get_type = $this->AutoEscalationmodel->getServiceName($case_no);

    $row = $db->query("SELECT * FROM escalation_matrix WHERE escalation_type=? AND category=?", 
                array('deescalate', $get_type))->row();

    if($remaining_days > 1)
    {
      $lm_new_target_days = ceil(($remaining_days*$row->lm_allocate_perc)/100);
      $sk_new_target_days = ceil(($remaining_days*$row->sk_allocate_perc)/100);
      $da_new_target_days = ceil(($remaining_days*$row->da_allocate_perc)/100);
      $co_new_target_days = ceil(($remaining_days*$row->co_allocate_perc)/100);
      $adc_new_target_days = ceil(($remaining_days*$row->adc_allocate_perc)/100);
    }
    else
    {
      $co_new_target_days = $remaining_days;
    }


  }


  // for service MUT/PART/NCAN
  public function revertFromDc($postData, $db)
  {
    // $allocate_day       = $postData['allocate_day'];
    $revert_to_user     = $postData['revert_to_user'];
    $case_no            = $postData['case_no'];
    $executionDate      = $postData['executionDate'];
    $revert_remarks     = $postData['revert_remarks'];
    // $dataArray          = json_decode($postData['dataArray'], true);var_dump($postData); die;

    // echo "<pre>"; var_dump($postData); echo "<br>"; die;

    $case_no_en         = $this->utilityclass->encryptJwtCase($case_no);
    $revert_to_user_en  = $this->utilityclass->encryptJwtCase($revert_to_user);

    // check if current date is holiday
    $isHoliday  = $this->getHoliday($db);
    $addHoliday = ($isHoliday == 1) ? 1:0;

    // details from escalation_details table
    $row = $this->getAllFromEscalationDetails($case_no, $db);
    $scode = $row->service_code;
    
    // get the diff with registered on and dc revert date that is current date
    if (ESCALATION_ALLOW_TIME == 1) 
    {
      $reg_on      = date('Y-m-d H:i', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d H:i', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d H:i', strtotime($row->assigned_date));
      $curr_date   = date('Y-m-d H:i');
    } 
    else {
      $reg_on      = date('Y-m-d', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d', strtotime($row->assigned_date));
      $curr_date   = date('Y-m-d');
    }

    // get service type
    $service_type = $this->Escalationmodel->getServiceNameForBlock($case_no);

    // days diff between case registered on date and current days
    $days_diff = $this->Escalationmodel->dateDiff($curr_date, $reg_on);
    $days_diff = $days_diff + $addHoliday; // if holiday available

    // check for de-escalation matrix from master table
    $de_escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, DEESCALATE, $db);
    $deescalateTimeLine = $de_escMatrixMaster->total_timeline;

    // check for de-escalation matrix from master table
    $escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, ESC_NORMAL, $db);
    $escalateTimeLine = $escMatrixMaster->total_timeline;

    // addition of escalation and de escalation time line
    $total_timeline = $deescalateTimeLine + $escalateTimeLine; 

    $row->total_days = $this->getExactTotalDays($reg_on);

    // if total days(escalation time zone) is less than total days diff
    $descalationStart = false;
    if($days_diff < $row->total_days)
    {
      // get no of users service wise
      $userCount = $this->getServiceWiseUserCount($service_type, 'normal');
      $descalationStart = false;
      $updatedTotalDays = $row->total_days;
    }
    if($days_diff > $row->total_days && $days_diff < $total_timeline)
    {
      // get no of users service wise
      $userCount = $this->getServiceWiseUserCount($service_type, 'deescalate');
      $updatedTotalDays = $deescalateTimeLine + $row->total_days;
      $descalationStart = true;
    }
    if($days_diff == $row->total_days && $days_diff < $total_timeline)
    {
      // get no of users service wise
      $userCount = $this->getServiceWiseUserCount($service_type, 'deescalate');
      $updatedTotalDays = $deescalateTimeLine + $row->total_days;
      $descalationStart = true;
    }

    // echo $days_diff ."==". $row->total_days ."&&". $days_diff ."<". $total_timeline; die;

    // get table name by service code
    $table = $this->Escalationmodel->getTableNameByServiceTypeForBlock($service_type);

    $sCase_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';

    $selectData = $db->query("SELECT * FROM $table WHERE $sCase_no=?", 
                    array($case_no))->row();

    $tableCircle = ($service_type==ALLOT_SERV)?'circle_code':'cir_code';

    $dist  = $selectData->dist_code;
    $sub   = $selectData->subdiv_code;
