        }

        // usecase 2: landed on CO, forwarded to LM, LM did nothing, escalate from  CO to DC
        // revert first pref: LM
        if(($row->lm_escalate_status == 'Y') &&
          ($row->sk_escalate_status == 'Y') &&
          $row->co_escalate_status == 'Y' &&
          ($row->adc_escalate_status == 'N' || $row->adc_escalate_status == null) &&
