            $total_distributed_days = $da_new_target_days + $lm_new_target_days + $co_new_target_days
                                      + $sk_new_target_days + $bo_new_target_days + $adc_new_target_days
                                      + $dc_new_target_days + $dept_new_target_days + $sro_new_target_days;

