      }

      // for service ACPP
      if($service_type == 'ACPP') // LRA —> LRS —> CO —> ADC —> DC
      {

        // usecase 1: landed on CO, co did nothing, escalate to DC
        // revert first pref: CO
        if(($row->lm_escalate_status == 'N' || $row->lm_escalate_status == null) &&
          ($row->sk_escalate_status == 'N' || $row->sk_escalate_status == null) &&
