          // get dc target days
          $dc_target_days = $row->dc_target_days+$deescalateTimeLine;

          // get the days when dc has been assigned
          $dc_reverted_days_diff = $this->Escalationmodel->dateDiff($curr_date, $assigned_on);

          // get when has dc reverted the case (in days). 
          // This will be the total rem days under esc time frame
          $dc_remain_days_after_revert = intval($dc_target_days - $dc_reverted_days_diff);

          // check if no of days greater than total users available
          if($dc_remain_days_after_revert > $userCount)
          {
            // get percentage wise date allocation for 
            $escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, 'deescalate', $db);

            // distribute the days to users percentage wise, and the remaining days add to LM, CO
            $lm_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->lm_allocate_perc)/100) + $addHoliday;
            $sk_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->sk_allocate_perc)/100);
            $co_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->co_allocate_perc)/100);
            $adc_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->adc_allocate_perc)/100);
            $dc_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->dc_allocate_perc)/100);

            $da_new_target_days   = 0;
            $bo_new_target_days   = 0;
            $dept_new_target_days = 0;
