                'response' => 1,
                'message'  => "#ERR18378: Failed to revert the case for case no $case_no",
                'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
              ];
              return $json;
            }

            // $db->trans_commit();
            log_message("error", "#ERR18388_SUCCESS: ".json_encode($db->last_query()));
            $json = [
              'response' => 3,
              'message'  => "#ERR18388: Successfully assigned days to all users for case no $case_no",
              'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
            ];
            return $json;
          }
        }

        // usecase 1: landed on CO, co did nothing, escalate to DC
        // revert first pref: CO
        if($row->lm_escalate_status == 'Y' && 
          ($row->sk_escalate_status == 'N' || $row->sk_escalate_status == null) &&
          $row->co_escalate_status == 'Y' &&
          ($row->adc_escalate_status == 'N' || $row->adc_escalate_status == null)  &&
          ($row->dc_escalate_status == 'N' || $row->dc_escalate_status == null))
        {
          $userCount = 5;

          // get dc target days
          $dc_target_days = $row->dc_target_days+$deescalateTimeLine;

          // get the days when dc has been assigned
          $dc_reverted_days_diff = $this->Escalationmodel->dateDiff($curr_date, $assigned_on);

          // get when has dc reverted the case (in days). 
          // This will be the total rem days under esc time frame
          $dc_remain_days_after_revert = intval($dc_target_days - $dc_reverted_days_diff);

          // check if no of days greater than total users available
          if($dc_remain_days_after_revert > $userCount)
          {
            // get percentage wise date allocation for 
            $escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, 'deescalate', $db);

            // distribute the days to users percentage wise, and the remaining days add to LM, CO
            $lm_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->lm_allocate_perc)/100);
            $sk_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->sk_allocate_perc)/100);
            $co_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->co_allocate_perc)/100) + $addHoliday;
            $adc_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->adc_allocate_perc)/100);
            $dc_new_target_days = ceil(($dc_remain_days_after_revert*$escMatrixMaster->dc_allocate_perc)/100);

            $da_new_target_days   = 0;
            $bo_new_target_days   = 0;
            $dept_new_target_days = 0;
            $sro_new_target_days  = 0;

            // check for total days to be distribute
            $total_distributed_days = $da_new_target_days + $lm_new_target_days 
                                      + $co_new_target_days + $sk_new_target_days 
                                      + $bo_new_target_days + $adc_new_target_days
                                      + $dc_new_target_days + $dept_new_target_days 
                                      + $sro_new_target_days;

            // making associative arrays for new target days user wise 
            $perArr = ['da'=>$da_new_target_days, 'lm'=>$lm_new_target_days, 'co'=>$co_new_target_days, 'sk'=>$sk_new_target_days, 'bo'=>$bo_new_target_days, 'adc'=>$adc_new_target_days, 'dc'=>$dc_new_target_days, 'dept'=>$dept_new_target_days, 'sro'=>$sro_new_target_days];

            arsort($perArr); // sort associative arrays in descending order, according to the value
            $key = array_keys($perArr); // get the key name having values

            // check if distribute days is less than remaining days
            if($total_distributed_days < $dc_remain_days_after_revert)
            {
              // get the remaining days after distribution
              $remaning_days_ad = $dc_remain_days_after_revert - $total_distributed_days;

              // add these/this remaining days to LM directly
              $lm_new_target_days = $lm_new_target_days + $remaning_days_ad;
            }

            // check if distribute days is greater than remaining days
            else if($total_distributed_days > $dc_remain_days_after_revert)
            {
              // get those extra days
              $extra_days = $total_distributed_days - $dc_remain_days_after_revert;

              // deduct those extra days from max hold user
              if($key[0] == 'da')
              {
                $da_new_target_days = $da_new_target_days - $extra_days;
              }
              if($key[0] == 'lm')
              {
                $lm_new_target_days = $lm_new_target_days - $extra_days;
              }
              if($key[0] == 'sk')
              {
                $sk_new_target_days = $sk_new_target_days - $extra_days;
              }
              if($key[0] == 'co')
              {
                $co_new_target_days = $co_new_target_days - $extra_days;
              }
              if($key[0] == 'bo')
              {
                $bo_new_target_days = $bo_new_target_days - $extra_days;
              }
              if($key[0] == 'adc')
              {
                $adc_new_target_days = $adc_new_target_days - $extra_days;
              }
              if($key[0] == 'dc')
              {
                $dc_new_target_days = $dc_new_target_days - $extra_days;
              }
              if($key[0] == 'dept')
              {
                $dept_new_target_days = $dept_new_target_days - $extra_days;
              }
              if($key[0] == 'sro')
              {
                $sro_new_target_days = $sro_new_target_days - $extra_days;
              }
            }

            $array = [
              'da_new_target_days'   => $da_new_target_days,
              'lm_new_target_days'   => $lm_new_target_days,
              'co_new_target_days'   => $co_new_target_days,
              'sk_new_target_days'   => $sk_new_target_days,
              'bo_new_target_days'   => $bo_new_target_days,
              'adc_new_target_days'  => $adc_new_target_days,
              'dc_new_target_days'   => $dc_new_target_days,
              'dept_new_target_days' => $dept_new_target_days,
              'sro_new_target_days'  => $sro_new_target_days,
              'scode'                => $scode,
              'service_type'         => $service_type,
              'esc_type'             => 'normal',
            ];

            // $db->trans_begin(); // begin of transaction

            // insert detail in escalation time zone table
            $insResp = $this->insertEscalationTimeZone($db, $case_no, $array);

            if($insResp != 'success')
            {
              // $db->trans_rollback();
              log_message("error", "#ERR17010_INSERTION_FAILED_ESC_TIME_ZONE: ".json_encode($db->last_query()));
              $json = [
                'response' => 1,
                'message'  => "#ERR17010: Failed to revert the case for case no $case_no",
                'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
              ];
              return $json;
            }

            $Interval = '+' . $co_new_target_days . ' days';
            $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));

            $total_days = $row->total_days + $total_distributed_days + $addHoliday;
            $to_be_completed_within_days = $co_new_target_days;
    

            // update escalation details table
            $updateEscDet = [
              
              'assigned_from'            => $dc,
              'assigned_from_code'       => 2,
              'assigned_to'              => $co,
              'assigned_to_code'         => 6,

              'assigned_date'            => date('Y-m-d H:i:s'),
              'escalated_date'           => $escalatedDate,
              'total_days'               => $total_days,
              'to_be_completed_within_days' => $to_be_completed_within_days,

              'da_target_days'           => $da_new_target_days + $row->da_target_days,
