              'lm_escalate_status'       => 'N',
              'sk_target_days'           => $sk_new_target_days + $row->sk_target_days,
              'sk_allocate_days'         => $sk_new_target_days + $row->sk_allocate_days,
              'sk_escalate_status'       => 'N',
              'co_target_days'           => $co_new_target_days + $row->co_target_days,
              'co_allocate_days'         => $co_new_target_days + $row->co_allocate_days,
              'co_escalate_status'       => 'N',
              'bo_target_days'           => $bo_new_target_days + $row->bo_target_days,
              'bo_allocate_days'         => $bo_new_target_days + $row->bo_allocate_days,
              'bo_escalate_status'       => 'N',
              'adc_target_days'          => $adc_new_target_days + $row->adc_target_days,
              'adc_allocate_days'        => $adc_new_target_days + $row->adc_allocate_days,
              'adc_escalate_status'      => 'N',
              'dc_target_days'           => $dc_reverted_days_diff,
              'dc_allocate_days'         => $dc_reverted_days_diff,
              'dc_completed_days'        => $dc_reverted_days_diff,
              'dc_escalate_status'       => 'N',
              'deescalation_start_date'  => date('Y-m-d h:i:s'),
              'deescalation_status'      => 'Y',
              'updated_date'             => date('Y-m-d h:i:s'),
            ];

            $db->where('case_no', $case_no);
            $db->update('escalation_details', $updateEscDet);
            if($db->affected_rows() != 1)
            {
              // $db->trans_rollback();
              log_message("error", "#ERR17064_UPDATTION_FAILED_ESC_DET ".json_encode($db->last_query()));
              $json = [
                'response' => 1,
                'message'  => "#ERR17064: Failed to revert the case for case no $case_no",
                'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
              ];
              return $json;
            }

            $dateCode = $this->Escalationmodel->generateDateCode();
            $dateCodes = $row->co_date_code_list;

            if ($dateCodes == null) 
            {
              $dateCodes = $dateCode;
            } 
            else 
            {
              $dateCodes = $dateCodes . ',' . $dateCode;
            }

            $executionDate = date('Y-m-d H:i:s');
            // 

            $task   = json_decode(DC_REVERT_TASK);
            $taskid = $task[0]->CODE;

            $date_history = $this->Escalationmodel->generateDateCode();

            $insertDateArray = [
              'sr_no'                  => $dateCode,
              'date_code'              => $date_history,
              'petition_no'            => $row->petition_no,
              'service_code'           => $row->service_code,
              'taskid'                 => $taskid,
              'pending_officer'        => $co,
              'assigned_user'          => $dc,
              'assigned_user_code'     => 2,
              'assigned_to'            => $co,
              'assigned_to_code'       => 6,
              'registerd_on'           => $row->registerd_on,
