  public function insertEscalationTimeZone($db, $case_no, $arr)
  {
    $row = $this->getAllFromEscalationDetails($case_no, $db);
    $row1 = $this->getFromEscalationMatrix($arr['scode'], $arr['service_type'], $arr['esc_type'], $db);

    // check if first proceeding is available
    $query = $db->query("SELECT * FROM escalation_time_zone WHERE proceeding_no=? 
              AND case_no=?", array(1, $case_no));

    if($query->num_rows() == 0)
    {
      //insert first proceeding into the escalation time zone table 
      $insertFirstProceed = [
        'proceeding_no'        => 1,
        'petition_no'          => $row->petition_no,
        'case_no'              => $row->case_no,
        'service_code'         => $row->service_code,
        'registerd_on'         => $row->registerd_on,
        'case_type'            => $row->case_type,
        'total_days'           => $row->total_days,
        'assignment_type'      => $row->assignment_type,
        'da_target_days'       => $row1->da_allocated_days,
        'lm_target_days'       => $row1->lm_allocated_days,
        'sk_target_days'       => $row1->sk_allocated_days,
        'co_target_days'       => $row1->co_allocated_days,
        'bo_target_days'       => $row1->bo_allocated_days,
        'adc_target_days'      => $row1->adc_allocated_days,
        'dc_target_days'       => $row1->dc_allocated_days,
        'dept_target_days'     => $row1->dept_allocated_days,
        'sro_target_days'      => $row1->sro_allocated_days,
        'mouzadar_target_days' => $row1->mouzadar_allocated_days,
        'created_date'         => date('Y-m-d H:i:s'),
      ];
      $ins = $db->insert('escalation_time_zone', $insertFirstProceed);
      if($ins != 1)
      {
        $db->trans_rollback();
        log_message('error', "#ERR1177: ".json_encode($ins));
        return 'fail';
      }
    }
     
    // get proceeding incremental value
    $max_proceed_no = $db->query("SELECT max(proceeding_no+1) as max_proceed_no 
                        FROM escalation_time_zone WHERE case_no=?", 
                          array($row->case_no))->row()->max_proceed_no;

    $new_total_days = $arr['da_new_target_days']+$arr['lm_new_target_days']+$arr['sk_new_target_days']+$arr['co_new_target_days']+$arr['adc_new_target_days']+$arr['dc_new_target_days'];

    //insert first proceeding into the escalation time zone table 
    $insertUpdatedDays = [
      'proceeding_no'        => $max_proceed_no,
      'petition_no'          => $row->petition_no,
      'case_no'              => $row->case_no,
      'service_code'         => $row->service_code,
      'registerd_on'         => $row->registerd_on,
      'case_type'            => $row->case_type,
      'total_days'           => $new_total_days,
      'assignment_type'      => $row->assignment_type,
      'da_target_days'       => $arr['da_new_target_days'],
      'lm_target_days'       => $arr['lm_new_target_days'],
      'sk_target_days'       => $arr['sk_new_target_days'],
      'co_target_days'       => $arr['co_new_target_days'],      
      'adc_target_days'      => $arr['adc_new_target_days'],
      'dc_target_days'       => $arr['dc_new_target_days'],      
      'created_date'         => date('Y-m-d H:i:s'),
    ];
    $insLatest = $db->insert('escalation_time_zone', $insertUpdatedDays);
    if($insLatest != 1)
    {
      $db->trans_rollback();
      log_message('error', "#ERR1224: ".json_encode($insLatest));
      return 'fail';
    }
    
    return 'success';
  }

  // get service user 
  public function getServiceWiseUserCount($service_type, $esc_cat)
  {
    $userCount = 0;

    if(($service_type == 'OMUT' || $service_type == 'OPART') && $esc_cat == 'normal')
    {
      $userCount = 3;
    }
    if($service_type == 'OMUT' && $esc_cat == 'deescalate')
    {
      $userCount = 3;
    }
    if($service_type == 'OPART' && $esc_cat == 'deescalate')
    {
      $userCount = 2;
    }

    if($service_type == 'MiNC' || $service_type == 'MiND' && ($esc_cat == 'deescalate' || $esc_cat == 'normal'))
    {
      $userCount = 3;
    }
      
    if($service_type == 'RECLASS' && ($esc_cat == 'deescalate' || $esc_cat == 'normal'))
    {
      $userCount = 4;
    }
    if(($service_type == 'FMUT' || $service_type == 'FPART') && ($esc_cat == 'deescalate' || $esc_cat == 'normal'))
    {
      $userCount = 2;
    }
    if($service_type == 'ACPP' && $esc_cat == 'normal')
    {
      $userCount = 5;
    }
    if($service_type == 'ACPP' && $esc_cat == 'deescalate')
    {
      $userCount = 4;
    }
    return $userCount;
  }

  
  // dc will assign days userwise manually
  public function manuallyReallocateDaysToUser($params, $db)
  {
    $json           = array();
    $case_no        = $params['case_no'];
    $executionDate  = $params['executionDate'];
    $revert_to_user = $params['revert_to_user'];
    $user           = $this->session->userdata('user_code');
    $remaining_days = $params['remaining_days'];
    $revert_remarks = $params['revert_remarks'];
    $to_be_reverted = $params['to_be_reverted'];
    $environment    = $params['environment'];

    if($params['revert_remarks'] == null || $params['revert_remarks'] == '')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR9539: Review remark is required for case no $case_no",
        'redirect' => $redirect,
      ];
      return $json;
    }

    $case_no_en        = $this->utilityclass->encryptJwtCase($case_no);
    $revert_to_user_en = $this->utilityclass->encryptJwtCase($revert_to_user);
    $redirect          = base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en;

    // get service_type
    $service_type = $this->explodeCaseNo($case_no);

    $task   = json_decode(DC_REVERT_TASK);
    $taskid = $task[0]->CODE;

    // check if current date is holiday
    $isHoliday  = $this->getHoliday($db);
    $addHoliday = ($isHoliday == 1) ? 1:0;

    // details from escalation_details table
    $row = $this->getAllFromEscalationDetails($case_no, $db);
    $scode = $row->service_code;
    
    // get the diff with registered on and dc revert date that is current date
    if (ESCALATION_ALLOW_TIME == 1) 
    {
      $reg_on = date('Y-m-d H:i', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d H:i', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d H:i', strtotime($row->assigned_date));
      $curr_date = date('Y-m-d H:i');
    } 
    else {
      $reg_on = date('Y-m-d', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d', strtotime($row->assigned_date));
      $curr_date = date('Y-m-d');
    }

    // days diff between case registered on date and current days
    $days_diff = $this->Escalationmodel->dateDiff($curr_date, $reg_on);
    $days_diff = $days_diff + $addHoliday; // if holiday available

    // check for de-escalation matrix from master table
    $de_escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, DEESCALATE, $db);
    $deescalateTimeLine = $de_escMatrixMaster->total_timeline;

    // check for de-escalation matrix from master table
    $escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, ESC_NORMAL, $db);
    $escalateTimeLine = $escMatrixMaster->total_timeline;

    // addition of escalation and de escalation time line
    $total_timeline = $deescalateTimeLine + $escalateTimeLine;

    // get table name by service code
    $table = $this->Escalationmodel->getTableNameByServiceTypeForBlock($service_type);

    $sCase_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';

    $selectData = $db->query("SELECT * FROM $table WHERE $sCase_no=?", 
                    array($case_no))->row();

    $tableCircle = ($service_type==ALLOT_SERV)?'circle_code':'cir_code';

    $dist  = $selectData->dist_code;
    $sub   = $selectData->subdiv_code;
    $cir   = $selectData->$tableCircle;
    $mouza = $selectData->mouza_pargona_code;
    $lot   = $selectData->lot_no;
    $vill  = $selectData->vill_townprt_code;

    // out of escalation and descalation, make es_flag = 0
    if($days_diff >= $total_timeline)
    {   
      if($service_type == 'MiNC')
      {
        $this->updateServiceTableMinC($table, $case_no, $db);
        $service_case_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';
        $updateServiceTable = $db->query("UPDATE $table SET is_escalated=? WHERE 
                                $service_case_no=?", array(0, $case_no));
        if($db->affected_rows() != 1)
        {
          log_message("error", "#ERR23591_UPDATION_FAILED_$table: ".json_encode($db->last_query()));
          $json = [
            'response' => 1,
            'message'  => "#SUCCESS23584: Case is already out of escalation as no time left for this case",
            'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
          ];
          return $json;
        }

        $updateEsc = $db->query("UPDATE escalation_details SET final_completion_date=?,
                      out_of_esc_status=?, updated_date=?, status=? WHERE case_no=?",
                        array(date('Y-m-d H:i:s'), 'y', date('Y-m-d H:i:s'), 'F', $case_no));
        if($db->affected_rows() != 1)
        {
          log_message("error", "#ERR4751_UPDATION_FAILED_IN_escalation_details: ".json_encode($db->last_query()));
          $json = [
            'response' => 1,
            'message'  => "#ERR4751: Failed to revert the case for case no $case_no",
            'view'     => 'EscalationRevertView/outOfEscDeesc',
            'go_back'  => $redirect_to_home,
          ];
          return $json;
        }
      } 
      else
      {
        $this->updateServiceTable($table, $case_no, $db);
        // return;
        $service_case_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';
        $updateServiceTable = $db->query("UPDATE $table SET is_escalated=? WHERE 
                                $service_case_no=?", array(0, $case_no));
        if($db->affected_rows() != 1)
        {
          log_message("error", "#ERR23591_UPDATION_FAILED_$table: ".json_encode($db->last_query()));
          $json = [
            'response' => 1,
            'message'  => "#SUCCESS23584: Case is already out of escalation as no time left for this case",
            'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
          ];
          return $json;
        }

        $updateEsc = $db->query("UPDATE escalation_details SET final_completion_date=?,
                      out_of_esc_status=?, updated_date=?, status=? WHERE case_no=?",
                        array(date('Y-m-d H:i:s'), 'y', date('Y-m-d H:i:s'), 'F', $case_no));
        if($db->affected_rows() != 1)
        {
          log_message("error", "#ERR4751_UPDATION_FAILED_IN_escalation_details: ".json_encode($db->last_query()));
          $json = [
            'response' => 1,
            'message'  => "#ERR4751: Failed to revert the case for case no $case_no",
            'view'     => 'EscalationRevertView/outOfEscDeesc',
            'go_back'  => $redirect_to_home,
          ];
          return $json;
        }
      }
    }

    $service_case_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';
    $updateServiceTable = $db->query("UPDATE $table SET is_escalated=? WHERE 
                            $service_case_no=?", array(0, $case_no));
    if($db->affected_rows() != 1)
    {
      log_message("error", "#ERR23591_UPDATION_FAILED_$table: ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23591: Failed to revert the case for case no $case_no",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    $dateCode     = $this->Escalationmodel->generateDateCode();
    $dateCodesLm  = $row->lm_date_code_list;
    $dateCodesSk  = $row->sk_date_code_list;
    $dateCodesCo  = $row->co_date_code_list;
    $dateCodesDa  = $row->da_date_code_list;
    $dateCodesAdc = $row->adc_date_code_list;
    $dateCodesDc  = $row->dc_date_code_list;

    $userDa       = $row->da_target_days;
    $userLm       = $row->lm_target_days;
    $userSk       = $row->sk_target_days;
    $userCo       = $row->co_target_days;
    $userAdc      = $row->adc_target_days;
    $userDc       = $row->dc_target_days;

    $dateCodesLm  = ($dateCodesLm == null && ($userLm != null || $userLm != 0))?'' : $dateCodesLm . ',' . $dateCode;
    $dateCodesSk  = ($dateCodesSk == null && ($userSk != null || $userSk != 0))?'' : $dateCodesSk . ',' . $dateCode;
    $dateCodesCo  = ($dateCodesCo == null && ($userCo != null || $userCo != 0))?'' : $dateCodesCo . ',' . $dateCode;
    $dateCodesDa  = ($dateCodesDa == null && ($userDa == null || $userDa == 0))?'' : $dateCodesDa . ',' . $dateCode;
    $dateCodesAdc = ($dateCodesAdc == null && ($userAdc != null || $userAdc != 0))?'' : $dateCodesAdc . ',' . $dateCode;
    $dateCodesDc  = ($dateCodesDc == null && ($userDc != null || $userDc != 0))?'' : $dateCodesDc . ',' . $dateCode;

    if(isset($params['allocate_days_to_lm']) && $params['allocate_days_to_lm'] == 0 && $to_be_reverted == 'LM')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23611: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }
    else if(isset($params['allocate_days_to_sk']) && $params['allocate_days_to_sk'] == 0 && $to_be_reverted == 'SK')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23620: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }
    else if(isset($params['allocate_days_to_da']) && $params['allocate_days_to_da'] == 0 && $to_be_reverted == 'AST')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23629: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }
    else if(isset($params['allocate_days_to_co']) && $params['allocate_days_to_co'] == 0 && $to_be_reverted == 'CO')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23638: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }
    else if(isset($params['allocate_days_to_adc']) && $params['allocate_days_to_adc'] == 0 && $to_be_reverted == 'ADC')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23647: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }
    else if(isset($params['allocate_days_to_dc']) && $params['allocate_days_to_dc'] == 0 && $to_be_reverted == 'DC')
    {
      $json = [
        'response' => 1,
        'message'  => "#ERR23656: The days must be assigned to $to_be_reverted, as it originally escalated from this user/officer",
        'redirect' => $redirect,
      ];
      return $json;
    }

    $reallocate_lm_days       = (isset($params['allocate_days_to_lm'])) ? (int) $params['allocate_days_to_lm'] : 0;
    $reallocate_sk_days       = (isset($params['allocate_days_to_sk'])) ? (int) $params['allocate_days_to_sk'] : 0;
    $reallocate_da_days       = (isset($params['allocate_days_to_da'])) ? (int) $params['allocate_days_to_da'] : 0;
    $reallocate_co_days       = (isset($params['allocate_days_to_co'])) ? (int) $params['allocate_days_to_co'] : 0;
    $reallocate_adc_days      = (isset($params['allocate_days_to_adc'])) ? (int) $params['allocate_days_to_adc'] : 0;
    $reallocate_dc_days       = (isset($params['allocate_days_to_dc'])) ? (int) $params['allocate_days_to_dc'] : 0;

    $pendingOfcr                 = null;
    $pendingOfcrCode             = null;
    $escalatedDate               = null;
    $to_be_completed_within_days = null;
    $executionDateNew = date('Y-m-d H:i:s');

    if($to_be_reverted == 'LM')
    {
      $pendingOfcr = $this->getPendingOfficerLM($dist,$sub,$cir,$mouza,$lot, $db)->user_code;
      $pendingOfcrCode = 9;
      $Interval = '+' . $reallocate_lm_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_lm_days;
    }
    else if($to_be_reverted == 'DC')
    {
      $pendingOfcr = $this->getPendingOfficerDC($dist,'DC', $db)->user_code;
      $pendingOfcrCode = 2;
      $Interval = '+' . $reallocate_dc_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_dc_days;
    }
    else if($to_be_reverted == 'ADC')
    {
      $pendingOfcr = $this->getPendingOfficerADC($dist,'ADC', $db)->user_code;
      $pendingOfcrCode = 3;
      $Interval = '+' . $reallocate_adc_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_adc_days;
    }
    else if($to_be_reverted == 'CO')
    {
      $pendingOfcr = $this->getPendingOfficer($dist,$sub,$cir,'CO', $db)->user_code;
      $pendingOfcrCode = 6;
      $Interval = '+' . $reallocate_co_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_co_days;
    }
    else if($to_be_reverted == 'AST')
    {
      $pendingOfcr = $this->getPendingOfficer($dist,$sub,$cir,'AST', $db)->user_code;
      $pendingOfcrCode = 8;
      $Interval = '+' . $reallocate_da_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_da_days;
    }
    else if($to_be_reverted == 'SK')
    {
      $pendingOfcr = $this->getPendingOfficer($dist,$sub,$cir,'SK', $db)->user_code;
      $pendingOfcrCode = 7;
      $Interval = '+' . $reallocate_sk_days . ' days';
      $escalatedDate = date('Y-m-d H:i:s', strtotime($executionDateNew . $Interval));
      $to_be_completed_within_days = $reallocate_sk_days;
    }

    $total_assign_days = $reallocate_da_days + $reallocate_lm_days + $reallocate_co_days + $reallocate_sk_days + $reallocate_adc_days + $reallocate_dc_days;

    // if remaining days is less than total allocated days by DC
    if($remaining_days < $total_assign_days)
    {
      log_message("error", "#ERR23633_ASSIGN_DAYS_MORE_THAN_REMAINING_DAYS: ".
            json_encode($remaining_days.'<'.$total_assign_days));
      $json = [
        'response' => 1,
        'message'  => "#ERR23633: Allocated days can not be more than remaining days for case no $case_no",
        'redirect' => $redirect,
      ];
      return $json;
    }

    // situation that need to handle
    $notHandled = [
      'case_no'                 => $case_no,
      'service_type'            => $service_type,
      'da_target_days'          => $row->da_target_days,
      'da_completed_days'       => $row->da_completed_days,
      'da_escalate_status'      => $row->da_escalate_status,
      'lm_target_days'          => $row->lm_target_days,
      'lm_completed_days'       => $row->lm_completed_days,
      'lm_escalate_status'      => $row->lm_escalate_status,
      'sk_target_days'          => $row->sk_target_days,
      'sk_completed_days'       => $row->sk_completed_days,
      'sk_escalate_status'      => $row->sk_escalate_status,
      'co_target_days'          => $row->co_target_days,
      'co_completed_days'       => $row->co_completed_days,
      'co_escalate_status'      => $row->co_escalate_status,
      'adc_target_days'         => $row->adc_target_days,
      'adc_completed_days'      => $row->adc_completed_days,
      'adc_escalate_status'     => $row->adc_escalate_status,
      'dc_target_days'          => $row->dc_target_days,
      'dc_completed_days'       => $row->dc_completed_days,
      'dc_escalate_status'      => $row->dc_escalate_status,
      'deescalation_start_date' => $row->deescalation_start_date,
      'deescalation_status'     => $row->deescalation_status,
    ];

    if($pendingOfcr == null || $pendingOfcr == '')
    {
      log_message("error", "#123SITUATION_NOT_HANDLED : ".json_encode($notHandled));
      $json = [
        'response' => 1,
        'message'  => "#ERR23523_NO_USER: Some issue occured in reverting the case for case no $case_no",
        'redirect' => $redirect,
      ];
      return $json;
    }

    $array = [
      'da_new_target_days'  => $reallocate_da_days,
      'lm_new_target_days'  => $reallocate_lm_days,
      'co_new_target_days'  => $reallocate_co_days,
      'sk_new_target_days'  => $reallocate_sk_days,
      'adc_new_target_days' => $reallocate_adc_days,
      'dc_new_target_days'  => $reallocate_dc_days,
      'scode'               => $row->service_code,
      'service_type'        => $service_type,
      'esc_type'            => $environment,
    ];

    // $db->trans_begin();

    $date_code_history = $this->getDateCode($user, $case_no, $db);
    $dc_rev_days       = $this->Escalationmodel->dateDiff($executionDate, $row->assigned_date);

    $total_days = $row->total_days + $total_distributed_days + $addHoliday;

    // update new reallocated days assigned by DC to users in escalation_details table
    $updateEscDet = [
      'total_days'             => $total_days,
      'assigned_from'          => $this->getPendingOfficerDC($dist,'DC', $db)->user_code,
      'assigned_from_code'     => 2,
      'assigned_to'            => $pendingOfcr,
      'assigned_to_code'       => $pendingOfcrCode,

      'assigned_date'          => date('Y-m-d H:i:s'),
      'escalated_date'         => $escalatedDate,

      'to_be_completed_within_days' => $to_be_completed_within_days,

      'da_target_days'         => $reallocate_da_days + $row->da_target_days,
      'da_allocate_days'       => $reallocate_da_days + $row->da_allocate_days,
      'da_escalate_status'     => 'N',
      'lm_target_days'         => $reallocate_lm_days + $row->lm_target_days,
      'lm_allocate_days'       => $reallocate_lm_days + $row->lm_allocate_days,
      'lm_escalate_status'     => 'N',
      'sk_target_days'         => $reallocate_sk_days + $row->sk_target_days,
      'sk_allocate_days'       => $reallocate_sk_days + $row->sk_allocate_days,
      'sk_escalate_status'     => 'N',
      'co_target_days'         => $reallocate_co_days + $row->co_target_days,
      'co_allocate_days'       => $reallocate_co_days + $row->co_allocate_days,
      'co_escalate_status'     => 'N',
      'adc_target_days'        => $reallocate_adc_days + $row->adc_target_days,
      'adc_allocate_days'      => $reallocate_adc_days + $row->adc_allocate_days,
      'adc_escalate_status'    => 'N',
      'dc_target_days'         => $dc_rev_days,
      'dc_allocate_days'       => $dc_rev_days,
      'dc_completed_days'      => $dc_rev_days,
      
      'updated_date'           => date('Y-m-d h:i:s'),

      'deescalation_status'    => ($environment == 'normal') ? null : 'Y',   
      'deescalation_start_date'=> ($environment == 'normal') ? null : date('Y-m-d H:i:s'),
    ];

    $where = $db->where('case_no', $case_no);
    $db->update('escalation_details', $updateEscDet, $where);
    if($db->affected_rows() != 1)
    {
      log_message("error", "#ERR23738_UPDATION_FAILED_IN_escalation_details: ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23738: Failed to revert the case for case no $case_no",
      ];
      return $json;
    }

    // insert detail in escalation time zone table
    $insResp = $this->insertEscalationTimeZone($db, $case_no, $array);

    if($insResp != 'success')
    {
      log_message("error", "#ERR23752_INSERTION_FAILED_ESC_TIME_ZONE: ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23752: Failed to revert the case for case no $case_no",
        'redirect' => $redirect,
      ];
      return $json;
    }

    // update escalation_dates_details table
    $sr_no = $this->Escalationmodel->generateDateCode();
    $date_history = $this->Escalationmodel->generateDateCode();

    $insertDateArray = [
      'sr_no'                  => $sr_no,
      'date_code'              => $date_history,
      'petition_no'            => $row->petition_no,
      'service_code'           => $row->service_code,
      'taskid'                 => $taskid,
      'pending_officer'        => $pendingOfcr,
      'assigned_user'          => $this->getPendingOfficerDC($dist,'DC', $db)->user_code,
      'assigned_user_code'     => 2,
      'assigned_to'            => $pendingOfcr,
      'assigned_to_code'       => $pendingOfcrCode,
      'registerd_on'           => $row->registerd_on,
      'allocation_date'        => $executionDate,
      'target_completion_date' => $escalatedDate,
      'date_diff'              => $this->Escalationmodel->dateDiff($escalatedDate, $executionDate),
      'escalated_status'       => 'N',
      'created_date'           => date('Y-m-d H:i:s'),
    ];
    $status = $db->insert('escalation_dates_details', $insertDateArray);
    // echo $db->last_query(); echo "<br>";
    if($status != 1)
    {
      log_message("error", "#ERR23785_INSERTION_FAILED_ESC_DATE_DET ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23785: Failed to revert the case for case no $case_no",
        'redirect' => $redirect,
      ];
      return $json;
    }

    // to update escalation dates details
    $history_id = $row->history_id;
    $completion_days_for_history = $this->Escalationmodel->dateDiff($executionDate, $row->assigned_date);
    $where_history = array(
      'petition_no' => $row->petition_no,
      'date_code'   => $date_history,
      'service_code'=> $row->service_code,
    );
    $updateDatesArray = array(
      'completion_date'  => $executionDate,
      'escalated_status' => 'N',
      'completion_days'  => $completion_days_for_history,
    );
    $db->update('escalation_dates_details', $updateDatesArray, $where_history);
    // echo $db->last_query(); echo "<br>";
    if($db->affected_rows() != 1)
    {
      log_message("error", "#ERR23822_UPDATION_FAILED_ESC_DATE_DET ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23812:Failed to revert the case for case no $case_no",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    // update again in escalation_details table to maintain history code
    $where_history_set = array(
      'petition_no' => $row->petition_no,
      'case_no'     => $row->case_no,
      'service_code'=> $row->service_code,
    );
    $updateDatesArraySet = array(
      'history_id'         => $date_history,
      'lm_date_code_list'  => $dateCodesLm,
      'sk_date_code_list'  => $dateCodesSk,
      'co_date_code_list'  => $dateCodesCo,
      'da_date_code_list'  => $dateCodesDa,
      'adc_date_code_list' => $dateCodesAdc,
      'dc_date_code_list'  => $date_history,
    );
    $db->update('escalation_details', $updateDatesArraySet, $where_history_set);
    // echo $db->last_query(); die;
    if($db->affected_rows() != 1)
    {
      log_message("error", "#ERR23914_UPDATION_FAILED_ESC_DET ".json_encode($db->last_query()));
      $json = [
        'response' => 1,
        'message'  => "#ERR23914: Failed to revert the case for case no $case_no",
        'redirect' => base_url()."index.php/DcEscalationController/revertEscalatedCase?case_no=".$case_no_en."&revert_to_user=".$revert_to_user_en,
      ];
      return $json;
    }

    log_message("error", "#ERR23924_SUCCESS: ".json_encode($db->last_query()));
    $json = [
      'response' => 3,
      'message'  => "#ERR23924: Successfully assigned days to the users for case no $case_no",
      'redirect' => base_url()."index.php/DcEscalationController/landingEscalatedViewPage",
    ];
    return $json;
  }

 

  // get DC remaining days
  public function getDcRemainingDaysToRevert($case_no, $revert_to_user, $db)
  {

    $json = array();
    $users = array();
    $userCount = 0;

    // details from escalation_details table
    $row   = $this->getAllFromEscalationDetails($case_no, $db);
    $scode = $row->service_code;

    $case_no_en         = $this->utilityclass->encryptJwtCase($case_no);
    $revert_to_user_en  = $this->utilityclass->encryptJwtCase($revert_to_user);

    $redirect_to_home = base_url()."index.php/DcEscalationController/landingEscalatedViewPage";

    // get the diff with registered on and dc revert date that is current date
    if (ESCALATION_ALLOW_TIME == 1) 
    {
      $reg_on      = date('Y-m-d H:i', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d H:i', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d H:i', strtotime($row->assigned_date));
      $curr_date   = date('Y-m-d H:i');
    } 
    else {
      $reg_on      = date('Y-m-d', strtotime($row->registerd_on));
      $will_esc_on = date('Y-m-d', strtotime($row->escalated_date));
      $assigned_on = date('Y-m-d', strtotime($row->assigned_date));
      $curr_date   = date('Y-m-d');
    }

    $row->total_days = $this->getExactTotalDays($reg_on);

    // get service type
    $service_type = $this->Escalationmodel->getServiceNameForBlock($case_no);

    // days diff between case registered on date and current days
    $days_diff = $this->Escalationmodel->dateDiff($curr_date, $reg_on);
    //get holiday count data///////from reg no(minus days diff to get working days)

    // check for de-escalation matrix from master table
    $de_escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, DEESCALATE, $db);
    $deescalateTimeLine = (int) $de_escMatrixMaster->total_timeline;

    // check for escalation matrix from master table
    $escMatrixMaster = $this->getFromEscalationMatrix($scode, $service_type, ESC_NORMAL, $db);
    $escalateTimeLine = (int) $escMatrixMaster->total_timeline;

    // addition of escalation and de escalation time line
    $total_timeline = $deescalateTimeLine + $escalateTimeLine;

    // get table name by service code
    $table = $this->Escalationmodel->getTableNameByServiceTypeForBlock($service_type);

    // situation that need to handle
    $notHandled = [
      'case_no'                 => $case_no,
      'service_type'            => $service_type,
      'da_target_days'          => $row->da_target_days,
      'da_completed_days'       => $row->da_completed_days,
      'da_escalate_status'      => $row->da_escalate_status,
      'lm_target_days'          => $row->lm_target_days,
      'lm_completed_days'       => $row->lm_completed_days,
      'lm_escalate_status'      => $row->lm_escalate_status,
      'sk_target_days'          => $row->sk_target_days,
      'sk_completed_days'       => $row->sk_completed_days,
      'sk_escalate_status'      => $row->sk_escalate_status,
      'co_target_days'          => $row->co_target_days,
      'co_completed_days'       => $row->co_completed_days,
      'co_escalate_status'      => $row->co_escalate_status,
      'adc_target_days'         => $row->adc_target_days,
      'adc_completed_days'      => $row->adc_completed_days,
      'adc_escalate_status'     => $row->adc_escalate_status,
      'dc_target_days'          => $row->dc_target_days,
      'dc_completed_days'       => $row->dc_completed_days,
      'dc_escalate_status'      => $row->dc_escalate_status,
      'deescalation_start_date' => $row->deescalation_start_date,
      'deescalation_status'     => $row->deescalation_status,
      'days_diff'               => (int) $days_diff,
      'total_timeline'          => $total_timeline,
      'row->total_days'         => $row->total_days,
    ];
    log_message("error", "#25137REM_DAYS_TO_REVERT_FROM_DC : ".json_encode($notHandled)); 
    // echo "<pre>";
    // var_dump(json_encode($notHandled)); die;

    $days_diff       = (int) $days_diff;
    $total_timeline  = (int) $total_timeline;
    $row->total_days = (int) $row->total_days;

    // out of escalation and descalation, make es_flag = 0
    if($days_diff >= $total_timeline)
    {     
      if($service_type == 'MiNC')
      {
        $this->updateServiceTableMinC($table, $case_no, $db); // update service wise table

        $service_case_no = ($service_type=='MiNC' || $service_type=='MiND')?'misc_case_no':'case_no';
        $updateServiceTable = $db->query("UPDATE $table SET is_escalated=? WHERE 
                                $service_case_no=?", array(0, $case_no));
