            'go_back'  => $redirect_to_home,
          ];
          return $json;
        }
      }
      
      if($db->affected_rows() != 1)
      {
        log_message("error", "#ERR4737_UPDATION_FAILED_IN_".$table.": ".json_encode($db->last_query()));
        $json = [
          'response' => 1,
          'message'  => "#ERR4737: Failed to revert the case for case no $case_no",
          'view'     => 'EscalationRevertView/outOfEscDeesc',
          'go_back'  => $redirect_to_home,
        ];
        return $json;
      }
      
      // update escalation details table
      $updateEsc = $db->query("UPDATE escalation_details SET final_completion_date=?,
                      out_of_esc_status=?, updated_date=?, status=? WHERE case_no=?",
                        array(date('Y-m-d H:i:s'), 'y', date('Y-m-d H:i:s'), 'F', $case_no));
      if($db->affected_rows() != 1)
      {
        log_message("error", "#ERR4751_UPDATION_FAILED_IN_escalation_details: ".json_encode($db->last_query()));
        $json = [
          'response' => 1,
          'message'  => "#ERR4751: Failed to revert the case for case no $case_no",
          'view'     => 'EscalationRevertView/outOfEscDeesc',
          'go_back'  => $redirect_to_home,
        ];
        return $json;
      }

      $json = [
        'response'          => 3,
        'message'           => "#WARNING4745: Total timeline : $total_timeline is overdued for case no $case_no. Case is out of escalation zone, it will be processed as normal case. Please Click on Back button to process with other case(s).",
        'view'              => 'EscalationRevertView/outOfEscDeesc',
        'go_back'           => $redirect_to_home,
      ];
      return $json;
    }

    if($service_type == 'MiNC') // LRA —> CO —> ADC
    {
      if($row->lm_escalate_status == 'Y' && $row->co_escalate_status == 'Y' &&
        ($row->adc_escalate_status == null || $row->adc_escalate_status == 'N'))
      { 
