      // get dc target days
      $dc_target_days = $row->dc_target_days;
      $environment = 'normal';

      // get the days when dc has been assigned
      $dc_days_diff = $this->Escalationmodel->dateDiff($curr_date, $assigned_on);

      if($dc_days_diff >= $dc_target_days) // revert days is more than target days
      {
        // add deescalation time frame
        $dc_target_days = $dc_target_days + $deescalateTimeLine;
        $environment = 'deescalate';
      }

      // check for remaining days now
      $dc_remaining_days = $dc_target_days - $dc_days_diff;

      if($dc_remaining_days > $userCount)
      {
        $json = [  
          'response'          => 4,
          'dc_remaining_days' => $dc_remaining_days,
          'userCount'         => $userCount,        
          'view'              => 'EscalationRevertView/escRevertBackFromDcToAllUsers',
          'users'             => $users,
          'environment'       => $environment,
          'process_code'      => '#24491',
        ];
        return $json;
      }
      else  // assign days to users manually
      {
        $json = [  
          'response'          => 4,
          'dc_remaining_days' => $dc_remaining_days,
          'userCount'         => $userCount,        
          'view'              => 'EscalationRevertView/escRevertBackFromDc',
          'environment'       => $environment,
          'process_code'      => '#24503',
          'users'             => $users,
          'from_dc_to'        => $revert_to_user_from_dc,
        ];
        return $json;
      }     
    }

    // escalation type = 'deescalate', greater than esc zone and less than de-esc zone
    if($days_diff >= $row->total_days && $days_diff < $total_timeline) 
    {
      // echo $days_diff .">=". $row->total_days ."&&". $days_diff ."<". $total_timeline; die;

      // echo "I am under deescalation"; die;
      // get dc target days
      $dc_target_days = $row->dc_target_days + $deescalateTimeLine;
      $environment    = 'deescalate';

      // get the days when dc has been assigned
      $dc_days_diff = $this->Escalationmodel->dateDiff($curr_date, $assigned_on);

      // check for remaining days now
      $dc_remaining_days = $dc_target_days - $dc_days_diff;

      // echo $dc_remaining_days ."|". $userCount; die;

      if($dc_remaining_days > $userCount)
      {
        $json = [  
          'response'          => 4,
          'dc_remaining_days' => $dc_remaining_days,
          'userCount'         => $userCount,        
          'view'              => 'EscalationRevertView/escRevertBackFromDcToAllUsers',
          'users'             => $users,
          'environment'       => $environment,
          'process_code'      => '#24491',
        ];
        return $json;
      }
      else  // assign days to users manually
      {
        $json = [  
          'response'          => 4,
          'dc_remaining_days' => $dc_remaining_days,
          'userCount'         => $userCount,        
          'view'              => 'EscalationRevertView/escRevertBackFromDc',
          'environment'       => $environment,
          'process_code'      => '#24503',
          'users'             => $users,
          'from_dc_to'        => $revert_to_user_from_dc,
        ];
        return $json;
      }
    }


  }

  public function getHoliday($db)
  {
    $date = date('Y-m-d');
    $query = $db->query("SELECT holiday_date FROM holiday_details WHERE holiday_date=?", array($date));
    return $query->num_rows();
  }

  protected function getPendingOfficerLM($d, $s, $c, $mouza_pargona_code, $lot_no, $db)
  {
      $sql = "select lt.user_code from loginuser_table lt join lm_code u on lt.dist_code=u.dist_code
          and lt.subdiv_code=u.subdiv_code
          and lt.cir_code=u.cir_code
          and lt.mouza_pargona_code=u.mouza_pargona_code
          and lt.lot_no=u.lot_no
          and u.lm_code=lt.user_code
          where lt.dis_enb_option='E'
          and lt.dist_code='$d'
          and lt.subdiv_code='$s' and lt.cir_code='$c' and lt.mouza_pargona_code='$mouza_pargona_code' and lt.lot_no='$lot_no'";
      $data = $db->query($sql);
      return $data->row();
  }

  protected function getPendingOfficerDC($d, $desig_code, $db)
  {
    $sql = "select u.username, lt.user_code, u.user_desig_code from loginuser_table 
              lt join users u on
                lt.dist_code=u.dist_code
                  and lt.subdiv_code=u.subdiv_code
                    and u.user_code=lt.user_code where lt.dis_enb_option='E'
                      and u.user_desig_code not like 'DCN%'
                        and u.user_desig_code like 'DC%'";
    $data = $db->query($sql);
    return $data->row();
  }

  protected function getPendingOfficerADC($d, $desig_code, $db)
  {
    $sql = "select u.username, lt.user_code, u.user_desig_code from loginuser_table lt join users u on
              lt.dist_code=u.dist_code
                and lt.subdiv_code=u.subdiv_code
                  and u.user_code=lt.user_code where lt.dis_enb_option='E'
                    and u.user_desig_code like 'ADC%'";
