  protected function getPendingOfficer($d, $s, $c, $desig_code, $db)
  {
    $sql = "select u.username, lt.user_code, u.user_desig_code from loginuser_table lt join users u on lt.dist_code=u.dist_code
        and lt.subdiv_code=u.subdiv_code and lt.cir_code=u.cir_code
        and u.user_code=lt.user_code where lt.dis_enb_option='E'
        and u.user_desig_code = '$desig_code' and lt.dist_code='$d'
        and lt.subdiv_code='$s' and lt.cir_code='$c'";
    $data = $db->query($sql);
    return $data->row();
  }


  protected function getExactTotalDays($registerd_on)
  {
    $currDate     = date('Y-m-d');
    $registerd_on = date('Y-m-d',strtotime($registerd_on));
    $total_diff   = $this->Escalationmodel->dateDiff($currDate,$registerd_on);
    $holidayDiff  = $this->Escalationmodel->getHolidayCountDetails($registerd_on, $currDate);
    $exactTime    = (int) $total_diff - (int) $holidayDiff;
    return $exactTime;
  }


  public function getEscalatedCasesToDcByOtherUsersByCaseNo($user_code,$from_user_code,$by_case_no)
  {
    $assigned_from_code = $this->EscTableFieldsModel->getUserCode($from_user_code);
    $escalate_status    = $this->EscTableFieldsModel->getEscalatedStatusByUserCode($from_user_code);

    if(!empty($by_case_no))
    {
      $query = $this->db->query("SELECT * FROM escalation_details WHERE $escalate_status = ? AND
                assigned_from_code = ? AND assigned_to_code=? AND status=?
                AND final_completion_date IS NULL AND 
                (dc_escalate_status=? OR dc_escalate_status IS NULL) AND case_no=?", 
                array('Y', $assigned_from_code, $user_code, '2', 'P', 'N', $by_case_no));
    }
    else
    {
      $query = $this->db->query("SELECT * FROM escalation_details WHERE $escalate_status = ? AND
                assigned_from_code = ? AND assigned_to_code=? AND status=?
                AND final_completion_date IS NULL AND 
                (dc_escalate_status=? OR dc_escalate_status IS NULL)", 
                array('Y', $assigned_from_code, $user_code, '2', 'P', 'N'));
    }      
    return $query;
  }


    

